<script setup lang="ts">
definePageMeta({ layout: false })
useSeoMeta({ title: 'Acceso editorial | Burbuja Política', robots: 'noindex, nofollow' })

const route = useRoute()
const router = useRouter()
const session = useCookie('bp-admin-demo-session', { maxAge: 60 * 60 * 8, sameSite: 'lax' })
const role = useCookie<'admin' | 'revision' | null>('bp-admin-demo-role', { maxAge: 60 * 60 * 8, sameSite: 'lax' })
const username = ref('')
const password = ref('')
const showPassword = ref(false)
const errorMessage = ref('')
const isSubmitting = ref(false)

function signIn() {
  isSubmitting.value = true
  errorMessage.value = ''
  const normalizedUsername = username.value.trim().toLowerCase()
  const isAdmin = normalizedUsername === 'admin' && password.value === 'admin'
  const isReviewer = normalizedUsername === 'revision' && password.value === 'revision'
  if (!isAdmin && !isReviewer) {
    errorMessage.value = 'El usuario o la contraseña no son correctos.'
    isSubmitting.value = false
    return
  }
  session.value = 'admin-demo'
  role.value = isAdmin ? 'admin' : 'revision'
  const requestedPath = typeof route.query.next === 'string' ? route.query.next : '/dasbuard'
  const safePath = requestedPath.startsWith('/') && !requestedPath.startsWith('//') ? requestedPath : '/dasbuard'
  router.push(isAdmin ? safePath : safePath === '/revision' ? safePath : '/revision')
}
</script>

